def algorithm(func, dim, lb, ub, budget, rng):
    x_best = (ub + lb) / 2 * np.ones(dim)
    for i in range(budget):
        x_new = x_best + rng.uniform(-1, 1, size=dim)
        x_new = np.clip(x_new, lb, ub)
        f_new = func(x_new)
        if f_new < func(x_best):
            x_best = x_new
    return x_best
